static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    GemmGroupNormSwishMultiplySwishCustomTilingData tiling;

    uint64_t sizeX = context->GetInputShape(0)->GetOriginShape().GetShapeSize();  // N*K
    uint64_t sizeW = context->GetInputShape(1)->GetOriginShape().GetShapeSize();  // M*K
    uint64_t sizeB = context->GetInputShape(2)->GetOriginShape().GetShapeSize();  // M

    if (sizeB == 0 || sizeW == 0) {
        return ge::GRAPH_FAILED;
    }
    uint32_t M = static_cast<uint32_t>(sizeB);
    uint32_t K = static_cast<uint32_t>(sizeW / sizeB);
    uint32_t N = static_cast<uint32_t>(sizeX / K);

    tiling.set_N(N);
    tiling.set_K(K);
    tiling.set_M(M);

    context->SetBlockDim(BLOCK_DIM);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *workspaceSizes = context->GetWorkspaceSizes(1);
    workspaceSizes[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

